def ci(a):
 a=np.asarray(a);h=t.ppf(.975,len(a)-1)*a.std(ddof=1)/np.sqrt(len(a));return a.mean(),a.mean()-h,a.mean()+h
# Generated tables: best values calculated rather than manually marked.
def table(caption,key,heads,rows,fmt):
 return '\\begin{table}[t]\n\\caption{'+caption+'}\n\\label{'+key+'}\n\\centering\\footnotesize\n\\begin{tabular}{@{}'+fmt+'@{}}\\toprule\n'+' & '.join(heads)+r'\\\midrule'+'\n'+'\n'.join(' & '.join(row)+r'\\' for row in rows)+r'\bottomrule'+'\n\\end{tabular}\n\\end{table}\n'
def val(x,n=4):return f'{x:.{n}f}'
def bestrows(df,dirs):
 a=[]
 for i,row in df.iterrows():
  cells=[i]
  for j,col in enumerate(df):
   x=row[col];best=df[col].max() if dirs[j]=='max' else df[col].min();v=val(x);cells.append(r'\textbf{'+v+'}' if x==best else v)
  a.append(cells)
 return a
macro=d[d.ranking=='entropy'].groupby('model')[['auroc','auprc','brier','ece']].mean().loc[models]
rank=d.groupby(['model','ranking']).aurc.mean().unstack().loc[models,['entropy','matched no D','matched full']]
T1=table('Class probability performance (identical across ranking rules). Bold indicates the best macro mean, not a significance claim.','tab:macro',['Classifier','AUROC','AUPRC','Brier','ECE'],bestrows(macro,['max','max','min','min']),'lrrrr')
T2=table('AURC by classifier and shared ranking protocol. Columns compare classifiers under the same feature definitions. Lower is better; column minima in bold.','tab:rank',['Classifier','Entropy','No $D$','With $D$'],bestrows(rank,['min']*3),'lrrr')
