T4=table('Within-classifier ranking contrasts in AURC. H = entropy. Shared features; unadjusted 95\\% intervals.','tab:rankci',['Classifier','Contrast','$\\Delta$','95\\% interval'],rows,'llrl')
rows=[]
for k in ['default','B=3','B=10','clip=.01','clip=.10','ridge=1','ridge=20','C=.1','C=10']:
 a=s[s.variant==k];v=ci(a.groupby('seed').delta.mean());rows.append([k,val(a.noD.mean(),5),val(a.full.mean(),5),val(v[0],5),'['+val(v[1],5)+', '+val(v[2],5)+']'])
T5=table('One-factor-at-a-time sensitivity: native AURA, full minus no-disagreement AURC. All intervals span zero.','tab:sens',['Setting','No $D$','Full','$\\Delta$','95\\% interval'],rows,'lrrrl')
native=d[(d.model=='AURA')&(d.ranking=='native full')].groupby('scenario')[['auroc','auprc','ece','aurc','risk80']].mean().loc[scenarios];threshold=th.groupby('scenario')[['coverage','risk']].mean().loc[scenarios];rows=[[lab,*[val(x) for x in native.loc[k]]] for lab,k in zip(labels,scenarios)]
